mapper.select:
SELECT , COALESCE(fs.management_area, 0) AS management_area, GREATEST(COALESCE(fs.management_area, 0) - COALESCE(rs.rented_area, 0), 0) AS rentable_area, COALESCE(rs.total_room_count, 0) AS total_room_count, COALESCE(rs.rentable_room_count, 0) AS rentable_room_count FROM ics_park p LEFT JOIN ( SELECT park_id, SUM(COALESCE(area, 0)) AS management_area FROM ics_floor GROUP BY park_id ) fs ON fs.park_id = p.id LEFT JOIN ( SELECT park_id, COUNT(1) AS total_room_count, SUM(CASE WHEN display_status = '0' THEN 1 ELSE 0 END) AS rentable_room_count, SUM(CASE WHEN display_status <> '0' THEN COALESCE(area, 0) ELSE 0 END) AS rented_area FROM ( SELECT r.park_id, r.area, CASE WHEN IFNULL(contract_room_status.has_exiting, 0) = 1 THEN '3' WHEN IFNULL(contract_room_status.has_expiring30, 0) = 1 THEN '5' WHEN IFNULL(contract_room_status.has_expiring90, 0) = 1 THEN '4' WHEN IFNULL(contract_room_status.has_active, 0) = 1 THEN '7' WHEN IFNULL(contract_room_status.has_expired, 0) = 1 THEN '6' ELSE r.status END AS display_status FROM ics_room r
) room_status GROUP BY park_id ) rs ON rs.park_id = p.id
AND p.id = #{park.id} AND p.name LIKE CONCAT('%', #{park.name}, '%') AND p.code LIKE CONCAT('%', #{park.code}, '%') AND p.status = #{park.status}
ORDER BY p.id DESC
